INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2022, 'Economia', NULL, 'Q1 Item 1 (TPS 2022): 1 4 7 10 13 16 19 22 24 Arbitrária fortuna! Desprezível Mais que essas almas vis, que a ti se humilham, Prosterne-se a teus pés o Brasil todo; Eu, nem curvo o joelho. […] Não – reduzir-me a pó, roubar-me tudo, Porém nunca aviltar-me pode o fado; Quem a morte não teme, nada teme Eu nisto só confio. [...] Cingida a fronte de sangrentos loiros Horror jamais inspirará meu nome; Nunca a viúva há de pedir-me o esposo, Nem seu pai a criança. Nunca aspirei a flagelar humanos. Meu nome acabe, para sempre | A primeira estrofe poderia ser redigida em prosa, mantendo-se o sentido original, da seguinte forma: Ainda que todo o Brasil se prosterne aos seus pés, eu não curvo o joelho à riqueza arbitrária, mais desprezível que as pessoas vis que se humilham diante dela.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q1 Item 2 (TPS 2022): 1 4 7 10 13 16 19 22 24 Arbitrária fortuna! Desprezível Mais que essas almas vis, que a ti se humilham, Prosterne-se a teus pés o Brasil todo; Eu, nem curvo o joelho. […] Não – reduzir-me a pó, roubar-me tudo, Porém nunca aviltar-me pode o fado; Quem a morte não teme, nada teme Eu nisto só confio. [...] Cingida a fronte de sangrentos loiros Horror jamais inspirará meu nome; Nunca a viúva há de pedir-me o esposo, Nem seu pai a criança. Nunca aspirei a flagelar humanos. Meu nome acabe, para sempre | A palavra “fado” (linha 6) é semanticamente próxima de “fortuna” (linha 1).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q1 Item 3 (TPS 2022): 1 4 7 10 13 16 19 22 24 Arbitrária fortuna! Desprezível Mais que essas almas vis, que a ti se humilham, Prosterne-se a teus pés o Brasil todo; Eu, nem curvo o joelho. […] Não – reduzir-me a pó, roubar-me tudo, Porém nunca aviltar-me pode o fado; Quem a morte não teme, nada teme Eu nisto só confio. [...] Cingida a fronte de sangrentos loiros Horror jamais inspirará meu nome; Nunca a viúva há de pedir-me o esposo, Nem seu pai a criança. Nunca aspirei a flagelar humanos. Meu nome acabe, para sempre | Ao repetir “meu nome” (linhas 10 e 14), José Bonifácio luta contra seu esquecimento por meio do apelo ao sacrifício pela Pátria.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q1 Item 4 (TPS 2022): 1 4 7 10 13 16 19 22 24 Arbitrária fortuna! Desprezível Mais que essas almas vis, que a ti se humilham, Prosterne-se a teus pés o Brasil todo; Eu, nem curvo o joelho. […] Não – reduzir-me a pó, roubar-me tudo, Porém nunca aviltar-me pode o fado; Quem a morte não teme, nada teme Eu nisto só confio. [...] Cingida a fronte de sangrentos loiros Horror jamais inspirará meu nome; Nunca a viúva há de pedir-me o esposo, Nem seu pai a criança. Nunca aspirei a flagelar humanos. Meu nome acabe, para sempre | Nas duas últimas estrofes, o autor expressa sua visão de que o Brasil poderia ter sido rival econômico do Velho Continente, mas se tornou presa de aves de rapina. Área Livre CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA TIPO “A” - MANHÃ PÁGINA 2/15', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q2 Item 1 (TPS 2022): 1 4 7 10 13 16 19 22 25 28 31 34 37 40 41 Para muitos de vós a curiosa e sugestiva exposição que gloriosamente inauguramos hoje é uma aglomeração de “horrores”. [...] Não está terminado o vosso espanto. Outros “horrores” vos esperam. [...] Nenhum preconceito é mais perturbador à concepção da arte que o da Beleza. [...] A arte é independente deste preconceito. [...] É a realização da nossa integração no Cosmos pelas emoções derivadas dos nossos sentidos, vagos e indefiníveis sentimentos que nos v | Na linha 21, a palavra “desencadeada” tem o sentido de reação em cadeia gerada pela “fantasia íntima”.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q2 Item 2 (TPS 2022): 1 4 7 10 13 16 19 22 25 28 31 34 37 40 41 Para muitos de vós a curiosa e sugestiva exposição que gloriosamente inauguramos hoje é uma aglomeração de “horrores”. [...] Não está terminado o vosso espanto. Outros “horrores” vos esperam. [...] Nenhum preconceito é mais perturbador à concepção da arte que o da Beleza. [...] A arte é independente deste preconceito. [...] É a realização da nossa integração no Cosmos pelas emoções derivadas dos nossos sentidos, vagos e indefiníveis sentimentos que nos v | Apesar de subjetivismo e objetivismo serem conceitos distintos e opostos, o autor opina que a liberdade permite a transformação do primeiro no segundo, de maneira que não pode ser prevista conforme normas científicas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q2 Item 3 (TPS 2022): 1 4 7 10 13 16 19 22 25 28 31 34 37 40 41 Para muitos de vós a curiosa e sugestiva exposição que gloriosamente inauguramos hoje é uma aglomeração de “horrores”. [...] Não está terminado o vosso espanto. Outros “horrores” vos esperam. [...] Nenhum preconceito é mais perturbador à concepção da arte que o da Beleza. [...] A arte é independente deste preconceito. [...] É a realização da nossa integração no Cosmos pelas emoções derivadas dos nossos sentidos, vagos e indefiníveis sentimentos que nos v | No excerto “No Brasil […] arte de vencidos” (linhas de 30 a 36), o autor ressalta a importância da alegria como método de superação da tristeza e da melancolia, substratos de nosso lirismo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q2 Item 4 (TPS 2022): 1 4 7 10 13 16 19 22 25 28 31 34 37 40 41 Para muitos de vós a curiosa e sugestiva exposição que gloriosamente inauguramos hoje é uma aglomeração de “horrores”. [...] Não está terminado o vosso espanto. Outros “horrores” vos esperam. [...] Nenhum preconceito é mais perturbador à concepção da arte que o da Beleza. [...] A arte é independente deste preconceito. [...] É a realização da nossa integração no Cosmos pelas emoções derivadas dos nossos sentidos, vagos e indefiníveis sentimentos que nos v | A ideia contida no último período do texto indica que a arte tem função metafórica, no sentido etimológico de transporte. Texto 1 para responder às questões 3 e 4. 1 4 7 10 13 16 19 22 25 28 30 Discurso sobre a história da literatura do Brasil Através das espessas trevas em que se achavam envolvidos os homens neste continente americano, viram-se alguns espíritos superiores brilhar de passagem, bem semelhantes a essas luzes errantes que o peregrino admira em solitária noi', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q3 Item 1 (TPS 2022): Com relação aos aspectos linguísticos e ao sentido do texto apresentado, julgue (C ou E) os itens a seguir. | O texto defende a concepção de que há autores demais no País, o que dificulta distinguir entre os que versejam por diletantismo e os que têm verdadeiro talento.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q3 Item 2 (TPS 2022): Com relação aos aspectos linguísticos e ao sentido do texto apresentado, julgue (C ou E) os itens a seguir. | A última frase do texto é uma ironia que exprime a crítica do autor ao desprezo dirigido aos literatos no Brasil.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q3 Item 3 (TPS 2022): Com relação aos aspectos linguísticos e ao sentido do texto apresentado, julgue (C ou E) os itens a seguir. | De acordo com o texto, as artes literárias encontram terreno fértil em uma terra onde haja liberdade.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q3 Item 4 (TPS 2022): Com relação aos aspectos linguísticos e ao sentido do texto apresentado, julgue (C ou E) os itens a seguir. | As vírgulas que separam as expressões “com razão” (linha 7) e “as ciências” (linha 16) justificam-se pela mesma explicação sintática. Área Livre CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA TIPO “A” - MANHÃ PÁGINA 3/15', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q4 Item 1 (TPS 2022): No que tange aos aspectos linguísticos e ao sentido do texto, julgue (C ou E) os itens a seguir. | O termo “fosfoream” (linha 6) possui sentido crítico e remete à debilidade dos produtores de arte no Brasil.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q4 Item 2 (TPS 2022): No que tange aos aspectos linguísticos e ao sentido do texto, julgue (C ou E) os itens a seguir. | O pronome pessoal “eles” (linha 5) relaciona-se ao seu antecedente “os homens” (linha 2).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q4 Item 3 (TPS 2022): No que tange aos aspectos linguísticos e ao sentido do texto, julgue (C ou E) os itens a seguir. | O sujeito da forma verbal “podem” (linha 20) é composto por dois núcleos: “escravidão” (linha 19) e “liberdade” (linha 19).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q4 Item 4 (TPS 2022): No que tange aos aspectos linguísticos e ao sentido do texto, julgue (C ou E) os itens a seguir. | Na linha 26, os pronomes oblíquos em “desmerecê-lo” e “desviá-lo” referem-se ambos a “literato” (linha 23). Área Livre Texto 2 para responder às questões 5 e 6. 1 4 7 10 13 16 19 22 25 28 29 A primeira das apresentações seria dedicada à pintura e à escultura; a segunda, à literatura, e a terceira à música. A notícia da Semana fora recebida “com um frêmito de curiosidade” nas rodas intelectuais e “altamente mundanas” de São Paulo, o que seria natural, pois se tratava da primeira tentativa de realizar no Brasil “um certame dessa natureza”. Os modernistas de São Paulo usavam habitualmente o termo “futurismo”, mas o faziam em sentido elástico, para designar as propostas mais ou menos renovadoras que se opunham às receitas “passadistas” e “acadêmicas”. A polarização futurismo x passadismo servi', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q5 Item 1 (TPS 2022): Com relação às ideias e aos sentidos do texto, julgue (C ou E) os itens a seguir. | Os poetas modernistas consideravam as propostas futuristas como inovadoras, pois elas indicavam uma ruptura radical com o passado academicista da literatura do século 19.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q5 Item 2 (TPS 2022): Com relação às ideias e aos sentidos do texto, julgue (C ou E) os itens a seguir. | Na linha 11, a contradição entre “futurismo” e “passadismo” define as propostas artísticas que se apresentavam no cenário artístico do início do século 20, o que representa realidades estéticas bem distintas e alheias uma à outra.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q5 Item 3 (TPS 2022): Com relação às ideias e aos sentidos do texto, julgue (C ou E) os itens a seguir. | O neologismo “‘bandeirantemente’” (linha 19) descreve, em linguagem conotativa, o pioneirismo de Mário de Andrade como modernista brasileiro e sua preferência por não se apresentar simplesmente como um artista regido pelos ideais futuristas de Marinetti, e sim por ideais libertários.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q5 Item 4 (TPS 2022): Com relação às ideias e aos sentidos do texto, julgue (C ou E) os itens a seguir. | A expressão “‘um certame dessa natureza’” (linha 6) caracteriza a Semana de Arte Moderna como uma investida brasileira inovadora, na qual produtos de categorias artísticas diversas foram apresentados. CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA TIPO “A” - MANHÃ PÁGINA 4/15', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q6 Item 1 (TPS 2022): Tendo em vista os aspectos linguísticos do texto, julgue (C ou E) os itens a seguir. | As expressões “mas o faziam em sentido elástico” (linha 8) e “atirar na lata de lixo do ‘passadismo’ manifestações variadas” (linhas 14 e 15) são exemplos da função referencial da linguagem, predominante nesse ensaio acerca da Semana de Arte Moderna.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q6 Item 2 (TPS 2022): Tendo em vista os aspectos linguísticos do texto, julgue (C ou E) os itens a seguir. | A citação de trecho do Manifesto Antropófago, de Oswald de Andrade, ilustra o emprego da intertextualidade a serviço da progressão textual e da coerência entre as ideias apresentadas a respeito dos “‘rapazes modernistas’” (linhas 20 e 21).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q6 Item 3 (TPS 2022): Tendo em vista os aspectos linguísticos do texto, julgue (C ou E) os itens a seguir. | O uso de aspas se justifica para marcar expressões informais de sentido ambíguo por ser texto escrito no nível formal da língua e concernente a tema relativo à cultura brasileira.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q6 Item 4 (TPS 2022): Tendo em vista os aspectos linguísticos do texto, julgue (C ou E) os itens a seguir. | Em “às quais, diga-se, não raro os próprios ‘novos’ estavam atados.” (linhas 15 e 16), a expressão iniciada pelo acento grave indicativo de crase é o complemento nominal do predicativo “atados”. Área Livre Texto 3 para responder às questões 7 e 8. 1 4 7 10 13 16 19 22 25 28 31 34 37 40 43 46 49 52 55 58 61 Seriam porventura dez horas da noite... Desde muitos dias os jornais vinham polindo a curiosidade pública, estufados de notícias e reclamos de festa. O Clube Automobilístico dava o seu primeiro grande baile. Tinham vindo de Londres as marcas do cotilhão e corria que as prendas seriam de sublimado gosto e valor. Os restaurantes anunciavam orgíacos revelhões de Natal. Os grêmios carnavalescos agitavam-se. Seriam porventura dez horas da noite quando esse homem entrou na praça Antônio Prado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q7 Item 1 (TPS 2022): No que tange às ideias, à forma e aos sentidos do texto, julgue (C ou E) os itens a seguir. | É plausível supor que o diálogo que ocorre no texto se dá entre um judeu recém-chegado a São Paulo e um oriental supostamente embriagado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q7 Item 2 (TPS 2022): No que tange às ideias, à forma e aos sentidos do texto, julgue (C ou E) os itens a seguir. | Observa-se, na descrição feita entre as linhas 28 e 32, uma crítica à aparência das mulheres presentes na praça, o que fica explícito no emprego do diminutivo no vocábulo “peitilhos” (linha 29).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q7 Item 3 (TPS 2022): No que tange às ideias, à forma e aos sentidos do texto, julgue (C ou E) os itens a seguir. | A forma verbal “Erravam” (linha 26) foi empregada no texto com o sentido de vaguear.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q7 Item 4 (TPS 2022): No que tange às ideias, à forma e aos sentidos do texto, julgue (C ou E) os itens a seguir. | A linguagem observada no texto é típica de textos literários.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q8 Item 1 (TPS 2022): Em relação aos aspectos linguísticos e aos sentidos do texto, julgue (C ou E) os itens a seguir. | Os vocábulos “porventura” (linhas 1 e 9) e “Decerto” (linha 54) são sinônimos e intercambiáveis no texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q8 Item 2 (TPS 2022): Em relação aos aspectos linguísticos e aos sentidos do texto, julgue (C ou E) os itens a seguir. | O pronome “lhe” (linha 17) foi empregado no texto com valor possessivo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q8 Item 3 (TPS 2022): Em relação aos aspectos linguísticos e aos sentidos do texto, julgue (C ou E) os itens a seguir. | No período “Tinham vindo de Londres as marcas do cotilhão e corria que as prendas seriam de sublimado gosto e valor” (linhas 5 e 6), as formas verbais “Tinham vindo” e “corria” têm sujeito posposto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q8 Item 4 (TPS 2022): Em relação aos aspectos linguísticos e aos sentidos do texto, julgue (C ou E) os itens a seguir. | A substituição do vocábulo “Onde” (linha 39) por Aonde, diferentemente do que se observa no texto, estaria de acordo com as normas de regência verbal. Área Livre Texto 4 para responder às questões 9 e 10. 1 4 7 10 13 16 19 22 25 28 31 34 37 40 43 46 49 52 54 Estava alegre nesse dia, bonita também. Um pouco de febre também. Por que esse romantismo: um pouco de febre? Mas a verdade é que tenho mesmo: olhos brilhantes, essa força e essa fraqueza, batidas desordenadas do coração. Quando a brisa leve, a brisa de verão, batia no seu corpo todo ele estremecia de frio e calor. E então ela pensava muito rapidamente, sem poder parar de inventar. Sempre a mesma queda: nem o mal nem a imaginação. No primeiro, no centro final, a sensação simples e sem adjetivos, tão cega quanto uma pedra rolando. Na im', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q9 Item 1 (TPS 2022): No que concerne às ideias e aos sentidos do texto, julgue (C ou E) os itens a seguir. | A alternância entre a primeira e a terceira pessoas do discurso, ao longo do texto, reflete a oscilação da personagem-narradora em sua relação consigo mesma: ora sente-se próxima e dona de si, ora sente-se distante e apartada de si mesma.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q9 Item 2 (TPS 2022): No que concerne às ideias e aos sentidos do texto, julgue (C ou E) os itens a seguir. | No trecho “Quem sou? Bem, isso já é demais.” (linhas 19 e 20), fica explícito o temperamento reservado da personagem e sua reticência em se expor.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q9 Item 3 (TPS 2022): No que concerne às ideias e aos sentidos do texto, julgue (C ou E) os itens a seguir. | No texto, a personagem é descrita como uma pessoa que tem “olhos brilhantes, essa força e essa fraqueza, batidas desordenadas do coração” (linhas 3 e 4), ao mesmo tempo em que “tem a força do mal, apenas a visão engrandecida e transformada” (linhas 10 e 11).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q9 Item 4 (TPS 2022): No que concerne às ideias e aos sentidos do texto, julgue (C ou E) os itens a seguir. | A piedade, segundo a personagem, está para ela assim como o medo e o desejo para determinadas pessoas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q10 Item 1 (TPS 2022): Com base nos aspectos linguísticos e nos sentidos do texto, julgue (C ou E) os itens a seguir. | A frase “No primeiro, no centro final, a sensação simples e sem adjetivos, tão cega quanto uma pedra rolando.” (linhas de 8 a 10) poderia ser reescrita, com manutenção das ideias originais e da correção gramatical do texto, da seguinte forma: Em um primeiro momento, no centro final, há uma sensação simples, sem adjetivos, tão cega quanto uma pedra que rola.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q10 Item 2 (TPS 2022): Com base nos aspectos linguísticos e nos sentidos do texto, julgue (C ou E) os itens a seguir. | Em ambos os trechos “Perdido pois o gosto de imaginar.” (linha 16) e “Pois ninguém se faz essas perguntas e eu...” (linhas 34 e 35), a conjunção “pois” está empregada com o mesmo sentido de porquanto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q10 Item 3 (TPS 2022): Com base nos aspectos linguísticos e nos sentidos do texto, julgue (C ou E) os itens a seguir. | A substituição da expressão “por que” (linha 41) por porque prejudicaria a correção textual, visto que inexiste relação de causalidade entre o trecho que a expressão inicia e o que a antecede.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q10 Item 4 (TPS 2022): Com base nos aspectos linguísticos e nos sentidos do texto, julgue (C ou E) os itens a seguir. | Segundo a narradora, escolher “novas veredas” (linha 13) representa o sentido máximo da liberdade. Área Livre Política Internacional Itens de 11 a 22', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q11 Item 1 (TPS 2022): Os processos e o projeto político da União Europeia (UE) estão atrelados historicamente à superação de crises internas e à construção de parcerias com outras regiões do mundo. A respeito do bloco da UE, julgue (C ou E) os itens a seguir. | Em 2019, Ursula von der Leyen tornou-se a primeira mulher a ocupar o cargo de presidente da Comissão Europeia. Nas diretrizes políticas que ela apresentou, von der Leyen centrou sua proposta de mandato em seis grandes ambições para a Europa, a saber: o estabelecimento de um Pacto Ecológico Europeu; o fortalecimento de uma economia a serviço das pessoas; a UE preparada para a era digital, com parâmetros seguros e éticos; a proteção do modo de vida europeu, embasado no estado de direito; a UE mais forte no mundo, trabalhando em prol de uma ordem global baseada em regras; e o fortalecimento da democracia dentro do próprio bloco.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q11 Item 2 (TPS 2022): Os processos e o projeto político da União Europeia (UE) estão atrelados historicamente à superação de crises internas e à construção de parcerias com outras regiões do mundo. A respeito do bloco da UE, julgue (C ou E) os itens a seguir. | A Romênia e a Bulgária foram aceitas como países-membros da UE em abril de 2005, após decisão do Conselho da UE. Todavia, a adesão das duas repúblicas ao Espaço Schengen vem sendo protelada, apesar dos pedidos do Parlamento Europeu para que a questão seja decidida.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q11 Item 3 (TPS 2022): Os processos e o projeto político da União Europeia (UE) estão atrelados historicamente à superação de crises internas e à construção de parcerias com outras regiões do mundo. A respeito do bloco da UE, julgue (C ou E) os itens a seguir. | A Declaração da Identidade Europeia, adotada na Cúpula de Copenhague, de dezembro de 1973, mobilizou a recém-expandida “Europa dos 9” a estabelecer, como elementos de sua identidade comum, a democracia representativa, o estado de direito, a justiça social e o respeito pelos direitos humanos. Esse compromisso, todavia, ainda não impunha padrões a futuras expansões do bloco, algo que viria a se concretizar somente com os critérios de Copenhague de 1993.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q11 Item 4 (TPS 2022): Os processos e o projeto político da União Europeia (UE) estão atrelados historicamente à superação de crises internas e à construção de parcerias com outras regiões do mundo. A respeito do bloco da UE, julgue (C ou E) os itens a seguir. | A Primeira Cúpula Brasil-UE, que ocorreu em Lisboa em 2007, focou em temas relacionados à cooperação técnica e à agenda política mundial, negligenciando a ainda existente necessidade de se concluir as negociações do Acordo de Associação Mercosul-UE, iniciadas em 1999.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q12 Item 1 (TPS 2022): As perspectivas teóricas das Relações Internacionais são tão diversas quanto as possibilidades de definição de seu objeto de estudo e de abordagens metodológicas. Considerando essas teorias, julgue (C ou E) os itens a seguir. | A racionalidade que sustenta as perspectivas realista e liberal das Relações Internacionais favorece o Estado como ator fundamental. Este é privilegiado por sua capacidade regulatória doméstica em detrimento das inerentes dificuldades encontradas na esfera internacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q12 Item 2 (TPS 2022): As perspectivas teóricas das Relações Internacionais são tão diversas quanto as possibilidades de definição de seu objeto de estudo e de abordagens metodológicas. Considerando essas teorias, julgue (C ou E) os itens a seguir. | Na perspectiva neorrealista, a soberania dos Estados não é um salvo-conduto, e mesmo Estados revolucionários acabam afetados pela estrutura internacional anárquica, pois são constrangidos a ajustarem seus comportamentos. CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA TIPO “A” - MANHÃ PÁGINA 7/15 3 As leituras teóricas que dialogam a partir do pós-colonialismo buscam evidenciar os vieses das leituras tradicionais das Relações Internacionais e, para tal, propõem, entre outras agendas, a discussão das diferenças e dos conhecimentos que foram epistemologicamente silenciados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q12 Item 3 (TPS 2022): As perspectivas teóricas das Relações Internacionais são tão diversas quanto as possibilidades de definição de seu objeto de estudo e de abordagens metodológicas. Considerando essas teorias, julgue (C ou E) os itens a seguir. | Os teóricos do neoliberalismo das Relações Internacionais diferenciam a interdependência enquanto instrumento retórico da interdependência como conceito analítico. À medida que a primeira enfatiza custos compartilhados na política internacional, a segunda avalia as dimensões da sensibilidade e a vulnerabilidade na busca da simetria nas relações entre os Estados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q13 Item 1 (TPS 2022): O Brasil assumiu, em 1o de janeiro de 2022, seu 11o mandato no Conselho de Segurança das Nações Unidas (CSNU), assumindo a condição, ao lado do Japão, de Estado-membro que mais vezes ocupou assento não permanente no órgão. No que tange a esse tema, julgue (C ou E) os itens a seguir. | No processo de criação da Organização das Nações Unidas (ONU) e de seu Conselho de Segurança, o Brasil chegou a ser cogitado como possível membro permanente pelo então presidente dos Estados Unidos da América (EUA), Franklin Delano Roosevelt, em função, principalmente, da participação da Força Expedicionária Brasileira (FEB) ao lado dos Aliados na Segunda Guerra Mundial. A sugestão de Roosevelt não avançou mormente pelas resistências interpostas pelo Reino Unido e pela União Soviética.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q13 Item 2 (TPS 2022): O Brasil assumiu, em 1o de janeiro de 2022, seu 11o mandato no Conselho de Segurança das Nações Unidas (CSNU), assumindo a condição, ao lado do Japão, de Estado-membro que mais vezes ocupou assento não permanente no órgão. No que tange a esse tema, julgue (C ou E) os itens a seguir. | Desde que assumiu seu novo mandato bianual (2022-2023), o Brasil voltou a participar das discussões atinentes à paz e à segurança internacionais no âmbito do Conselho, possuindo, além de voz nos debates, direito a voto nas questões procedimentais e substantivas levadas à atenção do colegiado. Entretanto, o Brasil, tal qual os demais Estados ocupando assentos rotativos, não possui o chamado “poder de veto”, à diferença do que sucede com os cinco membros permanentes do órgão – EUA, Federação Russa, França, Reino Unido e República Popular da China – nas votações substantivas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q13 Item 3 (TPS 2022): O Brasil assumiu, em 1o de janeiro de 2022, seu 11o mandato no Conselho de Segurança das Nações Unidas (CSNU), assumindo a condição, ao lado do Japão, de Estado-membro que mais vezes ocupou assento não permanente no órgão. No que tange a esse tema, julgue (C ou E) os itens a seguir. | Entre as medidas coercitivas que o Conselho de Segurança tem a prerrogativa de adotar, na forma de resolução, inclui-se a imposição de sanções econômicas multilaterais, com base no art. 41 da Carta da ONU. No entanto, a diplomacia brasileira tradicionalmente expressa oposição a esse recurso, manifestando preferência pela adoção de retaliações comerciais próprias, de caráter nacional, como forma de induzir a alteração do comportamento de Estados transgressores do direito internacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q13 Item 4 (TPS 2022): O Brasil assumiu, em 1o de janeiro de 2022, seu 11o mandato no Conselho de Segurança das Nações Unidas (CSNU), assumindo a condição, ao lado do Japão, de Estado-membro que mais vezes ocupou assento não permanente no órgão. No que tange a esse tema, julgue (C ou E) os itens a seguir. | A assiduidade como membro não permanente no CSNU, somada à participação efetiva em operações de manutenção da paz das Nações Unidas, é condição indispensável para o êxito de pleito a assento permanente no órgão. Por essa razão, tão logo o processo de reforma do órgão seja finalmente concluído, os membros do chamado G-4 (Brasil, Alemanha, Índia e Japão), além de dois Estados do continente africano que preencham tais critérios, serão admitidos como membros permanentes.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q14 Item 1 (TPS 2022): Na introdução do livro The Oxford Handbook of International Relations, Christian Reus-Smit e Duncan Snidal, afirmam: “First, theorizing takes place in relation to the questions (empirical and normative) we ask about the ‘international’ political universe. On the one hand, we construct theories to answer questions. [...] On the other hand, theorizing often generates questions.” [Tradução: Primeiramente, a teorização ocorre em relação às questões (empíricas ou normativas) que colocamos sobre o uni | Conforme os defensores da chamada Teoria da Paz Democrática, regimes autoritários encontram mais facilidade em lançarem seus Estados em conflitos bélicos, se comparados aos regimes democráticos, uma vez que sofrem relativamente pouco controle por parte dos Poderes Legislativo e Judiciário e por parte da opinião pública.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q14 Item 2 (TPS 2022): Na introdução do livro The Oxford Handbook of International Relations, Christian Reus-Smit e Duncan Snidal, afirmam: “First, theorizing takes place in relation to the questions (empirical and normative) we ask about the ‘international’ political universe. On the one hand, we construct theories to answer questions. [...] On the other hand, theorizing often generates questions.” [Tradução: Primeiramente, a teorização ocorre em relação às questões (empíricas ou normativas) que colocamos sobre o uni | A teoria crítica opõe-se tanto ao realismo quanto ao liberalismo por seus posicionamentos engajados, embora opostos, e propõe, ao contrário, a neutralidade e a imparcialidade dos cientistas na análise dos fenômenos internacionais. A teoria pós-estruturalista, por sua vez, enfatiza a anarquia no sistema internacional como um espaço de insegurança e de incerteza, apenas possível de ser superada pela cooperação entre os Estados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q14 Item 3 (TPS 2022): Na introdução do livro The Oxford Handbook of International Relations, Christian Reus-Smit e Duncan Snidal, afirmam: “First, theorizing takes place in relation to the questions (empirical and normative) we ask about the ‘international’ political universe. On the one hand, we construct theories to answer questions. [...] On the other hand, theorizing often generates questions.” [Tradução: Primeiramente, a teorização ocorre em relação às questões (empíricas ou normativas) que colocamos sobre o uni | Os liberais pregam a importância das organizações internacionais governamentais (OIGs) por essas aumentarem a previsibilidade, a estabilidade e a socialização de informações nas relações entre os atores. Os realistas ditam que as OIGs não alteram, de forma decisiva, as escolhas dos Estados, pois, em última instância, estes sempre estarão mais interessados nos ganhos relativos do que nos ganhos absolutos que a cooperação pode gerar.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q14 Item 4 (TPS 2022): Na introdução do livro The Oxford Handbook of International Relations, Christian Reus-Smit e Duncan Snidal, afirmam: “First, theorizing takes place in relation to the questions (empirical and normative) we ask about the ‘international’ political universe. On the one hand, we construct theories to answer questions. [...] On the other hand, theorizing often generates questions.” [Tradução: Primeiramente, a teorização ocorre em relação às questões (empíricas ou normativas) que colocamos sobre o uni | Na década de 1970, a área de Relações Internacionais sofreu forte influência de processos epistemológicos que se passavam nas ciências sociais em geral, com o objetivo de proporcionar maior objetividade e cientificidade às pesquisas. Um exemplo desse fenômeno foi a revolução behaviorista, que teve como consequências a maior influência das ciências exatas, o aumento da utilização de métodos quantitativos e o surgimento do debate acerca dos “níveis de análise” como instru', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q15 Item 1 (TPS 2022): A Política de Defesa Nacional (PDN) de 2005 estabeleceu, pela primeira vez, a concepção de um entorno estratégico do Brasil como uma região prioritária para a defesa nacional. Desde então, as versões revistas e atualizadas dessa política, publicadas nos anos de 2012, 2016 e 2020, têm mantido essa concepção, a qual também proporcionou orientações para a diplomacia brasileira em matéria de segurança internacional. Acerca desse assunto, julgue (C ou E) os itens a seguir. | A partir de 2005, o Brasil participou apenas de operações de paz realizadas em países que fazem parte do entorno estratégico brasileiro, a exemplo da Missão Multidimensional Integrada das Nações Unidas para a Estabilização da República Centro-Africana (Minusca).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q15 Item 2 (TPS 2022): A Política de Defesa Nacional (PDN) de 2005 estabeleceu, pela primeira vez, a concepção de um entorno estratégico do Brasil como uma região prioritária para a defesa nacional. Desde então, as versões revistas e atualizadas dessa política, publicadas nos anos de 2012, 2016 e 2020, têm mantido essa concepção, a qual também proporcionou orientações para a diplomacia brasileira em matéria de segurança internacional. Acerca desse assunto, julgue (C ou E) os itens a seguir. | O aumento da incidência de atos de pirataria nos Golfos da Guiné e de Áden constitui uma nova ameaça que recai sobre o entorno estratégico brasileiro, a qual a Marinha do Brasil deve estar preparada para combater.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q15 Item 3 (TPS 2022): A Política de Defesa Nacional (PDN) de 2005 estabeleceu, pela primeira vez, a concepção de um entorno estratégico do Brasil como uma região prioritária para a defesa nacional. Desde então, as versões revistas e atualizadas dessa política, publicadas nos anos de 2012, 2016 e 2020, têm mantido essa concepção, a qual também proporcionou orientações para a diplomacia brasileira em matéria de segurança internacional. Acerca desse assunto, julgue (C ou E) os itens a seguir. | Desde 2005, o entorno estratégico brasileiro tem sido caracterizado pela baixa ocorrência – ou até mesmo ausência – de conflitos armados interestatais, porém mantiveram-se elevados a violência doméstica e os conflitos armados intraestatais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q15 Item 4 (TPS 2022): A Política de Defesa Nacional (PDN) de 2005 estabeleceu, pela primeira vez, a concepção de um entorno estratégico do Brasil como uma região prioritária para a defesa nacional. Desde então, as versões revistas e atualizadas dessa política, publicadas nos anos de 2012, 2016 e 2020, têm mantido essa concepção, a qual também proporcionou orientações para a diplomacia brasileira em matéria de segurança internacional. Acerca desse assunto, julgue (C ou E) os itens a seguir. | A “Rota do Pacífico” é uma das principais rotas do tráfico internacional de drogas e atravessa quase todos os países que fazem parte do entorno estratégico brasileiro até chegar aos Estados Unidos da América.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q16 Item 1 (TPS 2022): O governo de Shinzo Abe (2012-2019) promoveu uma reorientação na política externa japonesa, com o propósito de estabelecer uma inserção internacional mais assertiva. Essa reorientação teve reflexo nas relações bilaterais e multilaterais do Japão com outros países, inclusive com o Brasil. A respeito dessas informações, julgue (C ou E) os itens a seguir. | Em 2014, durante a visita de Abe ao Brasil, os governos brasileiro e japonês anunciaram o estabelecimento da Parceria Estratégica e Global. Entre as ações previstas nessa parceria, está a adoção de um acordo de livre comércio entre o Mercosul e o Japão até 2030.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q16 Item 2 (TPS 2022): O governo de Shinzo Abe (2012-2019) promoveu uma reorientação na política externa japonesa, com o propósito de estabelecer uma inserção internacional mais assertiva. Essa reorientação teve reflexo nas relações bilaterais e multilaterais do Japão com outros países, inclusive com o Brasil. A respeito dessas informações, julgue (C ou E) os itens a seguir. | As políticas econômicas denominadas Abenomics tinham a finalidade de reaquecer a economia japonesa e de recuperar o prestígio internacional do país. São exemplos de objetivos dessas políticas a manutenção do crescimento econômico anual de 2,0% do PIB até 2020, o incentivo à inovação tecnológica, a promoção da exportação de produtos japoneses etc.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q16 Item 3 (TPS 2022): O governo de Shinzo Abe (2012-2019) promoveu uma reorientação na política externa japonesa, com o propósito de estabelecer uma inserção internacional mais assertiva. Essa reorientação teve reflexo nas relações bilaterais e multilaterais do Japão com outros países, inclusive com o Brasil. A respeito dessas informações, julgue (C ou E) os itens a seguir. | No âmbito da cooperação estratégico-militar, o governo Abe propôs a aliança Diamante de Segurança Democrática da Ásia, buscando garantir relações pacíficas entre Japão, Estados Unidos da América, Austrália e Índia. Essa aliança está embasada no princípio da segurança coletiva e prevê a criação de uma força conjunta entre os quatro países.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q16 Item 4 (TPS 2022): O governo de Shinzo Abe (2012-2019) promoveu uma reorientação na política externa japonesa, com o propósito de estabelecer uma inserção internacional mais assertiva. Essa reorientação teve reflexo nas relações bilaterais e multilaterais do Japão com outros países, inclusive com o Brasil. A respeito dessas informações, julgue (C ou E) os itens a seguir. | A remilitarização do Japão foi um dos objetivos da política externa de Abe. Para alcançar esse objetivo, o governo adotou, entre as iniciativas, a ampliação das possibilidades de emprego das Forças de Autodefesa (FAD) e a criação do Conselho de Segurança Nacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q17 Item 1 (TPS 2022): Os temas relacionados com o meio ambiente e o desenvolvimento sustentável historicamente estão presentes nas linhas de ação da política externa brasileira. No decorrer da realização da Conferência das Nações Unidas sobre Meio Ambiente e Desenvolvimento (Rio-92), o Brasil tornou-se o primeiro país a assinar a convenção sobre Diversidade Biológica (CDB) e tem sido bastante atuante nas negociações que ocorreram no âmbito dessa Convenção. A esse respeito, julgue (C ou E) os itens a seguir. | O Brasil participou de todo o processo negociador da CDB e defendeu o princípio da soberania estatal relacionado aos recursos naturais, contrastando com a posição dos países mais industrializados, os quais eram favoráveis ao acesso livre a esses recursos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q17 Item 2 (TPS 2022): Os temas relacionados com o meio ambiente e o desenvolvimento sustentável historicamente estão presentes nas linhas de ação da política externa brasileira. No decorrer da realização da Conferência das Nações Unidas sobre Meio Ambiente e Desenvolvimento (Rio-92), o Brasil tornou-se o primeiro país a assinar a convenção sobre Diversidade Biológica (CDB) e tem sido bastante atuante nas negociações que ocorreram no âmbito dessa Convenção. A esse respeito, julgue (C ou E) os itens a seguir. | A diplomacia brasileira atuou nas negociações relativas ao terceiro objetivo da CDB, com o propósito de estabelecer um regime internacional para a repartição justa e equitativa dos benefícios derivados da utilização dos recursos genéticos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q17 Item 3 (TPS 2022): Os temas relacionados com o meio ambiente e o desenvolvimento sustentável historicamente estão presentes nas linhas de ação da política externa brasileira. No decorrer da realização da Conferência das Nações Unidas sobre Meio Ambiente e Desenvolvimento (Rio-92), o Brasil tornou-se o primeiro país a assinar a convenção sobre Diversidade Biológica (CDB) e tem sido bastante atuante nas negociações que ocorreram no âmbito dessa Convenção. A esse respeito, julgue (C ou E) os itens a seguir. | O Brasil não assinou o Tratado Internacional sobre Recursos Fitogenéticos para a Alimentação e a Agricultura (TIRFAA), porque se opôs a um dos objetivos desse tratado, que previa o acesso livre e sem custos aos recursos fitogenéticos relacionados com a agricultura.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q17 Item 4 (TPS 2022): Os temas relacionados com o meio ambiente e o desenvolvimento sustentável historicamente estão presentes nas linhas de ação da política externa brasileira. No decorrer da realização da Conferência das Nações Unidas sobre Meio Ambiente e Desenvolvimento (Rio-92), o Brasil tornou-se o primeiro país a assinar a convenção sobre Diversidade Biológica (CDB) e tem sido bastante atuante nas negociações que ocorreram no âmbito dessa Convenção. A esse respeito, julgue (C ou E) os itens a seguir. | Quanto às negociações do Protocolo de Nagoia, o Brasil coordenou o Grupo dos Megadiversos e tornou-se um dos principais articuladores da defesa de posições comuns entre os países em desenvolvimento.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q18 Item 1 (TPS 2022): O Brasil atua em uma ampla agenda de negociações econômicas internacionais, tanto no âmbito bilateral quanto no multilateral. Considerando a trajetória da posição do Brasil nas negociações internacionais no que se refere a investimentos, julgue (C ou E) os itens a seguir. | Durante a Conferência Ministerial de Cingapura em 1996, foram iniciadas, na Organização Mundial do Comércio (OMC), discussões a respeito dos chamados “Temas de Cingapura” (investimentos, políticas de concorrência, transparência em compras públicas e facilitação de comércio). Na ocasião, o Brasil apoiou a proposta canadense de discussão do tema dos investimentos no âmbito da OMC e foi criado um grupo de trabalho específico concernente ao assunto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q18 Item 2 (TPS 2022): O Brasil atua em uma ampla agenda de negociações econômicas internacionais, tanto no âmbito bilateral quanto no multilateral. Considerando a trajetória da posição do Brasil nas negociações internacionais no que se refere a investimentos, julgue (C ou E) os itens a seguir. | Na década de 1990, com a expectativa de ampliar a atração de investimentos externos, o Brasil assinou 14 acordos de proteção e promoção de investimentos. Nenhum deles foi ratificado pelo Congresso Nacional, e os textos foram retirados em 2002.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q18 Item 3 (TPS 2022): O Brasil atua em uma ampla agenda de negociações econômicas internacionais, tanto no âmbito bilateral quanto no multilateral. Considerando a trajetória da posição do Brasil nas negociações internacionais no que se refere a investimentos, julgue (C ou E) os itens a seguir. | Em 2015, o Brasil assinou o Acordo sobre Cooperação e Facilitação de Investimentos (ACFI) com o Chile. O modelo de ACFI concebido pelo Brasil, a partir de então, reflete a abordagem original para o tratamento de investimentos, particularmente pelo fato de procurar prevenir controvérsias por meio de mecanismos de diálogo e, em última instância, prever mecanismo de arbitragem internacional entre investidores e Estados. CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA TIPO “A” - MANHÃ PÁGINA 9/15 4 O modelo brasileiro de ACFI está fundamentado em três pilares, que são mitigação de riscos; governança institucional; e agendas temáticas para cooperação e facilitação de investimentos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q19 Item 1 (TPS 2022): Desde o lançamento da Rodada Doha em 2001, o Brasil tem participado ativamente das negociações comerciais multilaterais na Organização Mundial do Comércio (OMC). Acerca da posição brasileira nas negociações na OMC, julgue (C ou E) os itens a seguir. | Na reunião miniministerial de Genebra, em julho de 2008, a coalizão G-20, liderada pelo Brasil, mantendo trajetória de atuação conjunta nas negociações agrícolas, iniciada na Conferência Ministerial de Cancún, em setembro de 2003, apresentou proposta no tema de acesso a mercados dos países em desenvolvimento, que incluía a abertura dos mercados da Índia e da China.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q19 Item 2 (TPS 2022): Desde o lançamento da Rodada Doha em 2001, o Brasil tem participado ativamente das negociações comerciais multilaterais na Organização Mundial do Comércio (OMC). Acerca da posição brasileira nas negociações na OMC, julgue (C ou E) os itens a seguir. | Em 2009, o Brasil exortou os membros da OMC a analisarem a questão da relação entre câmbio e comércio internacional. Para isso, defendeu a retomada do Grupo de Trabalho sobre Comércio, Dívida e Finanças (GTCDF), criado em 2001, no âmbito da Rodada Doha.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q19 Item 3 (TPS 2022): Desde o lançamento da Rodada Doha em 2001, o Brasil tem participado ativamente das negociações comerciais multilaterais na Organização Mundial do Comércio (OMC). Acerca da posição brasileira nas negociações na OMC, julgue (C ou E) os itens a seguir. | A posição brasileira na Conferência Ministerial de Bali, em 2013, foi favorável à inclusão do tema de facilitação ao comércio no pacote de resultados antecipados da Rodada Doha.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q19 Item 4 (TPS 2022): Desde o lançamento da Rodada Doha em 2001, o Brasil tem participado ativamente das negociações comerciais multilaterais na Organização Mundial do Comércio (OMC). Acerca da posição brasileira nas negociações na OMC, julgue (C ou E) os itens a seguir. | As negociações que ocorrem, desde 2008, no âmbito da Iniciativa da Declaração Conjunta sobre Comércio Eletrônico (Joint Statement Initiative – JSI) têm permitido ao Brasil vincular concessões acerca do comércio eletrônico à ampliação de compromissos dos Estados Unidos da América e da União Europeia no tema dos subsídios às exportações agrícolas. Área Livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q20 Item 1 (TPS 2022): No que concerne à Cooperação Sul-Sul implementada pelo Brasil, julgue (C ou E) os itens a seguir. | Da década de 1950 à década de 1990, o Brasil foi um receptor de cooperação externa, apesar de que, a partir da redemocratização, tenha começado a se engajar nas próprias parcerias de desenvolvimento por meio da prestação de cooperação à América Latina e aos países africanos lusófonos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q20 Item 2 (TPS 2022): No que concerne à Cooperação Sul-Sul implementada pelo Brasil, julgue (C ou E) os itens a seguir. | A expansão de recursos e o número de projetos de Cooperação Sul-Sul ao longo dos anos de 2005 a 2009 foram acompanhados pelo crescimento da presença no exterior de instituições públicas brasileiras, tais como a Empresa Brasileira de Pesquisa Agropecuária e a Fundação Oswaldo Cruz, envolvidas na provisão de cooperação técnica.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q20 Item 3 (TPS 2022): No que concerne à Cooperação Sul-Sul implementada pelo Brasil, julgue (C ou E) os itens a seguir. | Entre 2008 e 2012, a Agência Brasileira de Cooperação (ABC) priorizou projetos, nos países do Sul Global, com impactos sociais e econômicos de longo prazo, que aprimorariam as capacidades locais. Assim, para dar conta dos objetivos propostos, ocorreu reforma institucional na agência, proporcionando aprimoramento de recursos humanos, financeiros e logísticos para administrar o aumento da demanda e da complexidade dos projetos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q20 Item 4 (TPS 2022): No que concerne à Cooperação Sul-Sul implementada pelo Brasil, julgue (C ou E) os itens a seguir. | Um dos principais desafios da Cooperação Sul-Sul do Brasil está relacionado à coordenação de mais de 100 órgãos governamentais envolvidos na cooperação internacional. Dessa forma, a distribuição de prerrogativas e mandatos entre os ministérios e as agências bem como a relação deles com o Ministério de Relações Exteriores e a ABC não estão, com frequência, claramente delineados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q21 Item 1 (TPS 2022): O conceito de soberania é ubíquo na literatura de Relações Internacionais. No que concerne a esse tema, julgue (C ou E) os itens a seguir. | Para o neorrealismo, a soberania refere-se ao caráter das unidades, os Estados, que agem no sistema anárquico. O princípio da soberania garante a legitimidade das unidades e impele-as a agirem de maneira autárquica.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q21 Item 2 (TPS 2022): O conceito de soberania é ubíquo na literatura de Relações Internacionais. No que concerne a esse tema, julgue (C ou E) os itens a seguir. | Enquanto as perspectivas tradicionais tendem a avaliar a soberania como um dado ou atributo dos Estados, as leituras teóricas críticas enfatizam o caráter histórico e processual da construção desse princípio, bem como suas consequências sociais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q21 Item 3 (TPS 2022): O conceito de soberania é ubíquo na literatura de Relações Internacionais. No que concerne a esse tema, julgue (C ou E) os itens a seguir. | A criação da Organização das Nações Unidas limitou a consolidação da concepção de Estado soberano, mesmo que a Carta de 1945 afirme a igualdade soberana dos membros como um dos seus princípios e a membresia de novas nações seja baseada no respeito a esse.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q21 Item 4 (TPS 2022): O conceito de soberania é ubíquo na literatura de Relações Internacionais. No que concerne a esse tema, julgue (C ou E) os itens a seguir. | Para o construtivismo, a soberania é uma instituição e depende, assim, de entendimentos intersubjetivos, produzindo normas compartilhadas que impelem os Estados a justificarem suas ações perante a sociedade internacional. CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA TIPO “A” - MANHÃ PÁGINA 10/15', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q22 Item 1 (TPS 2022): “É como se a CPLP pudesse também significar a ‘Comunidade das Pontes de Língua Portuguesa’. A língua portuguesa é, aliás, ela própria, por seu caráter multicultural e por seu caráter universal, com componentes provindas de todas as partes do mundo, um traço de união fundamental para esse efeito.” Trecho de discurso do secretário-geral das Nações Unidas, António Guterres, na Sessão de Abertura da XI Conferência de Chefes de Estado e de Governo da Comunidade dos Países de Língua Portuguesa (CPLP), | Criada em 1996, a CPLP é integrada por nove Estados-membros, que são Brasil, Angola, Cabo Verde, Guiné-Bissau, Guiné Equatorial, Moçambique, Portugal, São Tomé e Príncipe e Timor-Leste. A exemplo de outras organizações intergovernamentais, a governança da CPLP é compartilhada entre a Presidência pro tempore, ocupada por Estado-membro em sistema de rotação, e uma estrutura burocrática chefiada por um(a) secretário(a)- executivo(a), responsável pelas incumbências tipicame', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q22 Item 2 (TPS 2022): “É como se a CPLP pudesse também significar a ‘Comunidade das Pontes de Língua Portuguesa’. A língua portuguesa é, aliás, ela própria, por seu caráter multicultural e por seu caráter universal, com componentes provindas de todas as partes do mundo, um traço de união fundamental para esse efeito.” Trecho de discurso do secretário-geral das Nações Unidas, António Guterres, na Sessão de Abertura da XI Conferência de Chefes de Estado e de Governo da Comunidade dos Países de Língua Portuguesa (CPLP), | A fundação da CPLP representou a materialização prática do antigo projeto, cujas raízes remontam aos albores do século 19, de constituição de entidade supranacional luso- brasileira, incluindo as ex-colônias portuguesas na África. Ao ratificarem sua adesão à CPLP, os demais países lusófonos optaram, voluntariamente, por outorgar a condução do processo decisório dentro do bloco ao condomínio Brasília-Lisboa, a quem cabe, por delegação, executar iniciativas bilaterais em ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q22 Item 3 (TPS 2022): “É como se a CPLP pudesse também significar a ‘Comunidade das Pontes de Língua Portuguesa’. A língua portuguesa é, aliás, ela própria, por seu caráter multicultural e por seu caráter universal, com componentes provindas de todas as partes do mundo, um traço de união fundamental para esse efeito.” Trecho de discurso do secretário-geral das Nações Unidas, António Guterres, na Sessão de Abertura da XI Conferência de Chefes de Estado e de Governo da Comunidade dos Países de Língua Portuguesa (CPLP), | A CPLP é a principal organização de segurança coletiva transatlântica estabelecida entre os países lusófonos. Entre as medidas que podem ser adotadas pelo Conselho de Ministros de Relações Exteriores da entidade, desde que por unanimidade, consta a possibilidade de autorização de intervenção militar, em nome da organização, e de emprego de operações de manutenção da paz em parceria com as Nações Unidas, em caso de ameaça à paz e à segurança internacionais ou de ruptura ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q22 Item 4 (TPS 2022): “É como se a CPLP pudesse também significar a ‘Comunidade das Pontes de Língua Portuguesa’. A língua portuguesa é, aliás, ela própria, por seu caráter multicultural e por seu caráter universal, com componentes provindas de todas as partes do mundo, um traço de união fundamental para esse efeito.” Trecho de discurso do secretário-geral das Nações Unidas, António Guterres, na Sessão de Abertura da XI Conferência de Chefes de Estado e de Governo da Comunidade dos Países de Língua Portuguesa (CPLP), | Um dos dez idiomas mais falados no mundo, a língua portuguesa não integra o conjunto de idiomas oficiais das Nações Unidas, que são o inglês, o francês, o espanhol, o árabe, o chinês (mandarim) e o russo. Como consequência, os delegados dos Estados-membros da CPLP não utilizam a língua portuguesa em seus pronunciamentos oficiais durante as reuniões e conferências organizadas sob o signo da Organização das Nações Unidas (ONU). A exceção é o Debate-Geral da Assembleia-Ger', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q23 Item 1 (TPS 2022): A expansão da fronteira agrícola moderna é um evento emblemático da dispersão do meio técnico, científico e informacional em parte do território brasileiro. Denominam-se fronteira agrícola moderna as áreas ocupadas, a partir da década de 1970, por monoculturas intensivas em capital e tecnologia, em substituição à vegetação original (principalmente de cerrado), a culturas tradicionais (praticadas por campesinos e (ou) agricultores familiares) e às áreas de pastagens extensivas. FREDERICO, Samuel. | Motivada por fatores econômicos e geopolíticos, a expansão da fronteira agrícola moderna ocorreu principalmente em direção às áreas de cerrado, também conhecidas como “polígono dos solos ácidos”.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q23 Item 2 (TPS 2022): A expansão da fronteira agrícola moderna é um evento emblemático da dispersão do meio técnico, científico e informacional em parte do território brasileiro. Denominam-se fronteira agrícola moderna as áreas ocupadas, a partir da década de 1970, por monoculturas intensivas em capital e tecnologia, em substituição à vegetação original (principalmente de cerrado), a culturas tradicionais (praticadas por campesinos e (ou) agricultores familiares) e às áreas de pastagens extensivas. FREDERICO, Samuel. | Com uma área superior a 1,2 milhão de quilômetros quadrados, equivalente a um quarto da extensão territorial brasileira, o cerrado possui condições topográficas (planalto, com grandes áreas planas e solos profundos) e climáticas (duas estações do ano bem definidas, uma chuvosa e outra seca, e intensa luminosidade) favoráveis à agricultura moderna.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q23 Item 3 (TPS 2022): A expansão da fronteira agrícola moderna é um evento emblemático da dispersão do meio técnico, científico e informacional em parte do território brasileiro. Denominam-se fronteira agrícola moderna as áreas ocupadas, a partir da década de 1970, por monoculturas intensivas em capital e tecnologia, em substituição à vegetação original (principalmente de cerrado), a culturas tradicionais (praticadas por campesinos e (ou) agricultores familiares) e às áreas de pastagens extensivas. FREDERICO, Samuel. | O meio técnico-científico informacional estende-se, de forma homogênea, como manchas ou pontos pelo território brasileiro.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q23 Item 4 (TPS 2022): A expansão da fronteira agrícola moderna é um evento emblemático da dispersão do meio técnico, científico e informacional em parte do território brasileiro. Denominam-se fronteira agrícola moderna as áreas ocupadas, a partir da década de 1970, por monoculturas intensivas em capital e tecnologia, em substituição à vegetação original (principalmente de cerrado), a culturas tradicionais (praticadas por campesinos e (ou) agricultores familiares) e às áreas de pastagens extensivas. FREDERICO, Samuel. | Quanto maior a especialização produtiva do campo e o respectivo conteúdo em ciência e informação, maior será a urbanização e a inter-relação entre o campo e a cidade.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q24 Item 1 (TPS 2022): A trama de ações envolvendo o ambiente está sendo paulatinamente institucionalizada por meio da ordem ambiental internacional, um conjunto de acordos internacionais sobre o ambiente para regular a ação humana na Terra, que passou a influenciar as práticas cotidianas. Nas décadas de 1980 e de 1990, ganhou notoriedade um sistema complexo de instrumentos internacionais tratando de temas ambientais com o objetivo de impedir o avanço da devastação ambiental, regular o acesso aos recursos naturais e,  | As primeiras convenções surgiram no início do século 19, na tentativa de regular a ação predatória em áreas mantidas como colônias pelas metrópoles europeias. CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA TIPO “A” - MANHÃ PÁGINA 11/15 2 A partir da Organização das Nações Unidas, a temática ambiental ganhou mais visibilidade, distinguindo-se um período até a reunião de Estocolmo, realizada em 1972, e outro que se seguiu a ele.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q24 Item 2 (TPS 2022): A trama de ações envolvendo o ambiente está sendo paulatinamente institucionalizada por meio da ordem ambiental internacional, um conjunto de acordos internacionais sobre o ambiente para regular a ação humana na Terra, que passou a influenciar as práticas cotidianas. Nas décadas de 1980 e de 1990, ganhou notoriedade um sistema complexo de instrumentos internacionais tratando de temas ambientais com o objetivo de impedir o avanço da devastação ambiental, regular o acesso aos recursos naturais e,  | Em Estocolmo, foram discutidos aspectos vinculados à poluição atmosférica e foi decidida a criação do Programa das Nações Unidas para o Meio Ambiente. (Pnuma), que passou a comandar as discussões ambientais em escala mundial.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q24 Item 3 (TPS 2022): A trama de ações envolvendo o ambiente está sendo paulatinamente institucionalizada por meio da ordem ambiental internacional, um conjunto de acordos internacionais sobre o ambiente para regular a ação humana na Terra, que passou a influenciar as práticas cotidianas. Nas décadas de 1980 e de 1990, ganhou notoriedade um sistema complexo de instrumentos internacionais tratando de temas ambientais com o objetivo de impedir o avanço da devastação ambiental, regular o acesso aos recursos naturais e,  | Outro momento de destaque foi a Conferência das Nações Unidas para o Meio Ambiente e Desenvolvimento (Cnumad), realizada no Rio de Janeiro em 1992.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q25 Item 1 (TPS 2022): Na otimização da produção e do processamento de commodities agrícolas, a infraestrutura e os serviços logísticos têm o papel de promover a circulação dos produtos nos mercados. Para os agentes econômicos, as ofertas e as demandas por serviços logísticos são imprescindíveis para as articulações socioespaciais do comércio global de soja e seus derivados, inclusive para a economia brasileira. PEREIRA, L. A. G.; SANTOS, I. J. F.; FERREIRA, W. R. Geografia do comércio de commodities, dinâmicas espaci | O mercado de produtos agroalimentares organiza-se em uma tríade composta por países da Europa Ocidental, dos Estados Unidos da América e do Japão, que controlam a produção e a comercialização de commodities agrícolas, a regulação dos preços desses produtos, bem como a cadeia produtiva e logística do setor.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q25 Item 2 (TPS 2022): Na otimização da produção e do processamento de commodities agrícolas, a infraestrutura e os serviços logísticos têm o papel de promover a circulação dos produtos nos mercados. Para os agentes econômicos, as ofertas e as demandas por serviços logísticos são imprescindíveis para as articulações socioespaciais do comércio global de soja e seus derivados, inclusive para a economia brasileira. PEREIRA, L. A. G.; SANTOS, I. J. F.; FERREIRA, W. R. Geografia do comércio de commodities, dinâmicas espaci | A comercialização da soja em grão, em farelo e em óleo envolve diversos serviços logísticos, como a armazenagem, o transporte entre as regiões produtoras, as unidades agroindustriais de processamento, a exportação e a entrega nos mercados consumidores.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q25 Item 3 (TPS 2022): Na otimização da produção e do processamento de commodities agrícolas, a infraestrutura e os serviços logísticos têm o papel de promover a circulação dos produtos nos mercados. Para os agentes econômicos, as ofertas e as demandas por serviços logísticos são imprescindíveis para as articulações socioespaciais do comércio global de soja e seus derivados, inclusive para a economia brasileira. PEREIRA, L. A. G.; SANTOS, I. J. F.; FERREIRA, W. R. Geografia do comércio de commodities, dinâmicas espaci | A regulação dos preços das commodities nos mercados futuros é ancorada na concessão de subsídios, que tem por objetivo manter os preços estáveis e evitar a concorrência desleal e o impacto dos custos dos serviços logísticos no preço final da soja e de seus derivados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q25 Item 4 (TPS 2022): Na otimização da produção e do processamento de commodities agrícolas, a infraestrutura e os serviços logísticos têm o papel de promover a circulação dos produtos nos mercados. Para os agentes econômicos, as ofertas e as demandas por serviços logísticos são imprescindíveis para as articulações socioespaciais do comércio global de soja e seus derivados, inclusive para a economia brasileira. PEREIRA, L. A. G.; SANTOS, I. J. F.; FERREIRA, W. R. Geografia do comércio de commodities, dinâmicas espaci | O transporte, o processamento de pedidos e a manutenção de estoques são serviços essenciais à logística de commodities agrícolas, com demanda de recursos financeiros de custeio. O transporte de cargas representa cerca de dois terços dos custos logísticos e de movimentação de mercadorias no mercado global. Área Livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q26 Item 1 (TPS 2022): Uma das especificidades da leitura que se pode denominar latino-americana sobre o território está ligada ao fato de que ela parte da esfera do vivido, das práticas ou, como enfatizava Milton Santos, do “uso” do território – mas um uso que se estende bem além do simples valor de uso, compreendendo também um expressivo valor simbólico. HAESBAERT, Rogério. Do corpo-território ao território-corpo (da Terra): contribuições decoloniais. GEOgraphia Niterói, Universidade Federal Fluminense ISSN 15177793 | Na geografia decolonial, a representação do território enquanto espaço de vida na América Latina utiliza o termo Pacha Mama como representação simbólica do corpo feminino em analogia à natureza, com destaque ao elemento indígena na América Andina.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q26 Item 2 (TPS 2022): Uma das especificidades da leitura que se pode denominar latino-americana sobre o território está ligada ao fato de que ela parte da esfera do vivido, das práticas ou, como enfatizava Milton Santos, do “uso” do território – mas um uso que se estende bem além do simples valor de uso, compreendendo também um expressivo valor simbólico. HAESBAERT, Rogério. Do corpo-território ao território-corpo (da Terra): contribuições decoloniais. GEOgraphia Niterói, Universidade Federal Fluminense ISSN 15177793 | Em período recente, os estudos latino-americanos da geografia têm desenvolvido elementos anteriormente invisibilizados ou que previamente eram concebidos sob uma perspectiva eurocêntrica.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q26 Item 3 (TPS 2022): Uma das especificidades da leitura que se pode denominar latino-americana sobre o território está ligada ao fato de que ela parte da esfera do vivido, das práticas ou, como enfatizava Milton Santos, do “uso” do território – mas um uso que se estende bem além do simples valor de uso, compreendendo também um expressivo valor simbólico. HAESBAERT, Rogério. Do corpo-território ao território-corpo (da Terra): contribuições decoloniais. GEOgraphia Niterói, Universidade Federal Fluminense ISSN 15177793 | O homem enquanto espécie ou população, em seu caráter coletivo, é entendido como elemento quantitativo e neutro na perspectiva decolonial, pois é agente neutro em relação ao Estado, mas agente político das relações de poder.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q26 Item 4 (TPS 2022): Uma das especificidades da leitura que se pode denominar latino-americana sobre o território está ligada ao fato de que ela parte da esfera do vivido, das práticas ou, como enfatizava Milton Santos, do “uso” do território – mas um uso que se estende bem além do simples valor de uso, compreendendo também um expressivo valor simbólico. HAESBAERT, Rogério. Do corpo-território ao território-corpo (da Terra): contribuições decoloniais. GEOgraphia Niterói, Universidade Federal Fluminense ISSN 15177793 | A colonização da América Latina tem como traço marcante a incorporação da população indígena como agente político do processo de ocupação do território.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q27 Item 1 (TPS 2022): O clima e a hidrologia têm influência fundamental na ecologia e dinâmica das várzeas amazônicas e nas atividades econômicas das suas populações humanas. Mesmo na região da Amazônia Central, próxima ao Equador, uma distinta sazonalidade da precipitação e de outros parâmetros climáticos podem ser observados [...]. Essa sazonalidade aumenta em direção ao sul e ao norte, respectivamente, resultando na transição da floresta tropical úmida para o bioma savânico do centro-oeste brasileiro (cerrado) no  | No bioma Amazônia, os meses mais quentes correspondem ao verão no hemisfério sul (de dezembro a março), estação climática caracterizada por temperaturas médias acima de 30 graus e elevado período de chuvas torrenciais com eventuais estiagens.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q27 Item 2 (TPS 2022): O clima e a hidrologia têm influência fundamental na ecologia e dinâmica das várzeas amazônicas e nas atividades econômicas das suas populações humanas. Mesmo na região da Amazônia Central, próxima ao Equador, uma distinta sazonalidade da precipitação e de outros parâmetros climáticos podem ser observados [...]. Essa sazonalidade aumenta em direção ao sul e ao norte, respectivamente, resultando na transição da floresta tropical úmida para o bioma savânico do centro-oeste brasileiro (cerrado) no  | Na Amazônia, há intensa variação da insolação no transcorrer das estações climáticas do ano. O verão (de dezembro a março) apresenta altos índices de insolação em comparação ao inverno (de junho a setembro), estação em que os dias são mais curtos e com menor radiação solar. CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA TIPO “A” - MANHÃ PÁGINA 12/15 3 O bioma Amazônia tem como elemento natural estruturante o rio Amazonas e seus afluentes, a segunda maior ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q27 Item 3 (TPS 2022): O clima e a hidrologia têm influência fundamental na ecologia e dinâmica das várzeas amazônicas e nas atividades econômicas das suas populações humanas. Mesmo na região da Amazônia Central, próxima ao Equador, uma distinta sazonalidade da precipitação e de outros parâmetros climáticos podem ser observados [...]. Essa sazonalidade aumenta em direção ao sul e ao norte, respectivamente, resultando na transição da floresta tropical úmida para o bioma savânico do centro-oeste brasileiro (cerrado) no  | Os rios do bioma Amazônia apresentam sazonalidade nas precipitações e nos pulsos monomodais de inundação; há rios que recebem água do degelo dos Andes e das chuvas e outros abastecidos pela pluviosidade. O ciclo de inundação e vazante impacta as diversas paisagens que compõem o bioma.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q28 Item 1 (TPS 2022): No Brasil, o plantio da cana-de-açúcar foi uma das primeiras atividades econômicas implantadas por Portugal durante o período colonial. Nas décadas seguintes, o Brasil enfrentou contextos de auge e de decadência dessa economia agroexportadora. Mais recentemente, a partir dos anos de 1930, a reorganização da estrutura produtiva do setor agroindustrial canavieiro teve como forte marca a ação do Estado por meio de planos e programas de incentivo. No que tange à dinâmica produtiva recente da ativida | O Instituto do Açúcar e do Álcool (IAA), criado em 1933, teve forte intervenção estatal, dominando praticamente toda a estrutura do setor, sendo responsável pelo ciclo de produção e comercialização, inclusive de fixação de preços, cotas, exportação e importação. Dessa forma, um dos principais papéis do IAA foi incentivar o consumo e regular o mercado de açúcar e álcool no Brasil.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q28 Item 2 (TPS 2022): No Brasil, o plantio da cana-de-açúcar foi uma das primeiras atividades econômicas implantadas por Portugal durante o período colonial. Nas décadas seguintes, o Brasil enfrentou contextos de auge e de decadência dessa economia agroexportadora. Mais recentemente, a partir dos anos de 1930, a reorganização da estrutura produtiva do setor agroindustrial canavieiro teve como forte marca a ação do Estado por meio de planos e programas de incentivo. No que tange à dinâmica produtiva recente da ativida | Em 1975, foi criado o Programa Nacional do Álcool (Proálcool), que incentivou a produção de etanol anidro e hidratado, além de desenvolver a cogeração de energia por meio do bagaço e da palha da cana-de-açúcar. O Proálcool foi consequência do forte impacto na economia nacional, causado pelos dois choques do petróleo (OPEP) em 1973 e em 1979, respectivamente.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q28 Item 3 (TPS 2022): No Brasil, o plantio da cana-de-açúcar foi uma das primeiras atividades econômicas implantadas por Portugal durante o período colonial. Nas décadas seguintes, o Brasil enfrentou contextos de auge e de decadência dessa economia agroexportadora. Mais recentemente, a partir dos anos de 1930, a reorganização da estrutura produtiva do setor agroindustrial canavieiro teve como forte marca a ação do Estado por meio de planos e programas de incentivo. No que tange à dinâmica produtiva recente da ativida | No ano de 2006, o governo brasileiro, por intermédio do Ministério da Agricultura, Pecuária e Abastecimento (MAPA) e da Secretaria de Produção e Agroenergia, lançou o Plano de Desenvolvimento de Biocombustíveis, inserido no contexto global da busca por novas fontes de energia, sobretudo as renováveis, promovendo a expansão de usinas canavieiras para produção de etanol, consorciadas ao processamento de biodiesel.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q28 Item 4 (TPS 2022): No Brasil, o plantio da cana-de-açúcar foi uma das primeiras atividades econômicas implantadas por Portugal durante o período colonial. Nas décadas seguintes, o Brasil enfrentou contextos de auge e de decadência dessa economia agroexportadora. Mais recentemente, a partir dos anos de 1930, a reorganização da estrutura produtiva do setor agroindustrial canavieiro teve como forte marca a ação do Estado por meio de planos e programas de incentivo. No que tange à dinâmica produtiva recente da ativida | A legislação brasileira que estabelece a Política Nacional de Biocombustíveis (RenovaBio) foi criada após a Conferência das Nações Unidas sobre as Mudanças Climáticas de 2015 (COP 21). Um dos seus objetivos foi criar metas nacionais anuais de descarbonização para o setor de combustíveis, de forma a incentivar o aumento da produção e da participação de biocombustíveis na matriz energética de transportes do Brasil. Área Livre Direito Itens de 29 a 34', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q29 Item 1 (TPS 2022): No que tange ao direito administrativo brasileiro, em suas múltiplas configurações dogmáticas e jurisprudenciais, julgue (C ou E) os itens a seguir. | Para os fins definidos na Lei de Licitações e Contratos Administrativos, bens e serviços especiais são aqueles cujos padrões de desempenho e qualidade podem ser objetivamente definidos pelo edital, por meio de especificações usuais de mercado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q29 Item 2 (TPS 2022): No que tange ao direito administrativo brasileiro, em suas múltiplas configurações dogmáticas e jurisprudenciais, julgue (C ou E) os itens a seguir. | Segundo a jurisprudência do Supremo Tribunal Federal, a ação por danos causados por agente público deve ser ajuizada contra o Estado ou a pessoa jurídica de direito privado prestadora de serviço público, sendo parte ilegítima para a ação o autor do ato, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa, conforme interpretação do art. 37, § 6o, da Constituição Federal.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q29 Item 3 (TPS 2022): No que tange ao direito administrativo brasileiro, em suas múltiplas configurações dogmáticas e jurisprudenciais, julgue (C ou E) os itens a seguir. | Constitui ato de improbidade administrativa importando em enriquecimento ilícito, mediante a prática de ato doloso, utilizar, em obra ou serviço particular, qualquer bem móvel, de propriedade ou à disposição de qualquer dos Poderes Executivo, Legislativo e Judiciário, bem como da administração direta e indireta, no âmbito da União, dos estados, dos municípios e do Distrito Federal, bem como o trabalho de servidores, de empregados ou de terceiros contratados por essas entidades.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q29 Item 4 (TPS 2022): No que tange ao direito administrativo brasileiro, em suas múltiplas configurações dogmáticas e jurisprudenciais, julgue (C ou E) os itens a seguir. | Ao servidor do Serviço Exterior Brasileiro (SEB), submetido aos princípios de hierarquia e disciplina, incumbe observar o conjunto de deveres, atribuições e responsabilidades previstas na legislação, nas disposições regulamentares que regimentam o SEB, no exercício de suas funções, exceto em sua conduta pessoal na vida privada. Área Livre CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA TIPO “A” - MANHÃ PÁGINA 13/15', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q30 Item 1 (TPS 2022): Quanto às áreas além dos limites da jurisdição exclusiva dos Estados em suas múltiplas configurações legais, dogmáticas e jurisprudenciais, julgue (C ou E) os itens a seguir. | De acordo com o Tribunal Internacional do Direito do Mar, com base no disposto no art. 110 da Convenção das Nações Unidas sobre o Direito do Mar, o Estado costeiro tem o direito de exercer o poder de polícia em sua zona econômica exclusiva por meio de navio de guerra, não lhe sendo possível conferir tal poder a outras autoridades estatais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q30 Item 2 (TPS 2022): Quanto às áreas além dos limites da jurisdição exclusiva dos Estados em suas múltiplas configurações legais, dogmáticas e jurisprudenciais, julgue (C ou E) os itens a seguir. | Um navio de guerra de qualquer Estado pode abordar e inspecionar um navio estrangeiro em alto mar, desde que tal embarcação não seja um navio de guerra ou utilizado em serviço oficial não comercial, quando se tratar de navio que se dedica à pirataria ou ao tráfico de escravos. Nesses casos, tem-se a hipótese de exercício da jurisdição universal pelo Estado da bandeira do navio de guerra.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q30 Item 3 (TPS 2022): Quanto às áreas além dos limites da jurisdição exclusiva dos Estados em suas múltiplas configurações legais, dogmáticas e jurisprudenciais, julgue (C ou E) os itens a seguir. | Conforme o projeto revisado do texto de um acordo referente à utilização sustentável da biodiversidade marinha para além da jurisdição nacional, de 27 de novembro de 2019, o aproveitamento dos recursos genéticos marinhos da Antártica deve ocorrer em benefício da humanidade como um todo, levando em consideração os interesses e as necessidades dos Estados em desenvolvimento, especialmente aqueles sem litoral e geograficamente desfavorecidos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q30 Item 4 (TPS 2022): Quanto às áreas além dos limites da jurisdição exclusiva dos Estados em suas múltiplas configurações legais, dogmáticas e jurisprudenciais, julgue (C ou E) os itens a seguir. | No que concerne à utilização da área, o descumprimento de disposição contratual pela parte patrocinada em face da Autoridade Internacional dos Fundos Marinhos implica automaticamente a responsabilidade internacional do Estado patrocinador, quando houver dano e nexo causal entre o dano e a parte patrocinada. Não tendo essa personalidade jurídica internacional, não será possível sua responsabilização. Área Livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q31 Item 1 (TPS 2022): No que tange ao estudo acerca do direito dos tratados, bem como à atuação dos órgãos e das agências subsidiárias da Organização das Nações Unidas (ONU) no interesse da promoção da paz mundial, julgue (C ou E) os itens a seguir. | De acordo com a Convenção de Viena sobre o Direito dos Tratados, um tratado deverá ser interpretado, em regra, pelo sentido comum atribuível aos seus termos, admitindo-se ainda a possibilidade de se recorrer a meios suplementares de interpretação.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q31 Item 2 (TPS 2022): No que tange ao estudo acerca do direito dos tratados, bem como à atuação dos órgãos e das agências subsidiárias da Organização das Nações Unidas (ONU) no interesse da promoção da paz mundial, julgue (C ou E) os itens a seguir. | As Convenções e as Recomendações da Organização Internacional do Trabalho (OIT) apresentam distinções tanto no âmbito formal quanto na esfera material, visto que cada uma delas detém particulares e específicas prerrogativas de abrangência temática.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q31 Item 3 (TPS 2022): No que tange ao estudo acerca do direito dos tratados, bem como à atuação dos órgãos e das agências subsidiárias da Organização das Nações Unidas (ONU) no interesse da promoção da paz mundial, julgue (C ou E) os itens a seguir. | Em que pese a Corte Interamericana de Direitos Humanos tenha, historicamente, apresentado uma composição de juízes com formação jurídica, tal requisito não é exigido pelos diplomas e regulamentos internacionais que integram o Sistema Interamericano de Proteção dos Direitos Humanos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q31 Item 4 (TPS 2022): No que tange ao estudo acerca do direito dos tratados, bem como à atuação dos órgãos e das agências subsidiárias da Organização das Nações Unidas (ONU) no interesse da promoção da paz mundial, julgue (C ou E) os itens a seguir. | Como meio diplomático para evitar o uso da força na resolução das controvérsias internacionais, a oferta de bons ofícios configura-se quando uma terceira parte, na figura de um ou mais Estados, uma instituição internacional ou um alto funcionário de determinada organização internacional, de forma amigável, atua como uma facilitadora na aproximação das partes em litígio, sem, normalmente, emitir proposta de solução para o conflito.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q32 Item 1 (TPS 2022): Considerando as normas e os procedimentos acordados no âmbito da Organização Mundial do Comércio (OMC) e do Mercosul, assim como a jurisprudência dos respectivos mecanismos de solução de controvérsias, julgue (C ou E) os itens a seguir. | O Acordo sobre Aspectos dos Direitos de Propriedade Intelectual Relacionados ao Comércio (Acordo TRIPS, na sigla em inglês) impede o licenciamento compulsório de patentes farmacêuticas (“quebra de patentes”).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q32 Item 2 (TPS 2022): Considerando as normas e os procedimentos acordados no âmbito da Organização Mundial do Comércio (OMC) e do Mercosul, assim como a jurisprudência dos respectivos mecanismos de solução de controvérsias, julgue (C ou E) os itens a seguir. | Opiniões consultivas são solicitações que Estados-partes podem dirigir ao Tribunal Permanente de Revisão do Mercosul. De igual maneira, o Órgão de Apelação da OMC possui competência para apreciar opiniões consultivas a ele encaminhadas por Estados-membros dessa organização.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q32 Item 3 (TPS 2022): Considerando as normas e os procedimentos acordados no âmbito da Organização Mundial do Comércio (OMC) e do Mercosul, assim como a jurisprudência dos respectivos mecanismos de solução de controvérsias, julgue (C ou E) os itens a seguir. | O Protocolo de Olivos para a Solução de Controvérsias no Mercosul permite que uma decisão adotada por órgão de solução de controvérsias do Mercosul seja objeto de recurso ao Órgão de Apelação da OMC.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q32 Item 4 (TPS 2022): Considerando as normas e os procedimentos acordados no âmbito da Organização Mundial do Comércio (OMC) e do Mercosul, assim como a jurisprudência dos respectivos mecanismos de solução de controvérsias, julgue (C ou E) os itens a seguir. | Conforme a jurisprudência dos mecanismos de solução de controvérsias da OMC, a exceção de segurança do art. XXI do Acordo Geral sobre Tarifas e Comércio (GATT) não é “autodeterminável”. Em consequência, a invocação dessa exceção por um estado-membro em uma disputa não retira a jurisdição dos órgãos de solução de controvérsias para avaliar se estão atendidas as condições estabelecidas por aquele artigo. CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA TIPO “A” - MANHÃ PÁGINA 14/15', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q33 Item 1 (TPS 2022): Tendo em vista o estágio atual do direito internacional do mar na sociedade internacional, com o reconhecimento da atuação crescente de organizações e tribunais internacionais, respectivamente, na resolução de problemas globais e de controvérsias internacionais, julgue (C ou E) os itens a seguir. | A Comissão de Limites da Plataforma Continental (CLPC), composta por 21 membros peritos em geologia, geofísica ou hidrografia, tem por função, entre outras, examinar os dados e outros elementos de informação, apresentados pelos Estados costeiros acerca dos limites exteriores da plataforma continental nas zonas em que tais limites se estenderem além de 200 milhas marítimas, bem como formular recomendações aos Estados costeiros de acordo com o art. 76 da Convenção das Nações Unidas sobre o Direito do Mar (CNUDM) e com a Declaração de Entendimento, adotada em 29 de agosto de 1980, pela Terceira Conferência das Nações Unidas sobre o Direito do Mar.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q33 Item 2 (TPS 2022): Tendo em vista o estágio atual do direito internacional do mar na sociedade internacional, com o reconhecimento da atuação crescente de organizações e tribunais internacionais, respectivamente, na resolução de problemas globais e de controvérsias internacionais, julgue (C ou E) os itens a seguir. | Apresentando como órgãos principais uma assembleia, um conselho e um secretariado, a Autoridade Internacional dos Fundos Marinhos (ISBA) tem jurisdição limitada à área (zona) abrangendo o leito do mar, os fundos marinhos e o seu subsolo, além dos limites da jurisdição nacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q33 Item 3 (TPS 2022): Tendo em vista o estágio atual do direito internacional do mar na sociedade internacional, com o reconhecimento da atuação crescente de organizações e tribunais internacionais, respectivamente, na resolução de problemas globais e de controvérsias internacionais, julgue (C ou E) os itens a seguir. | No caso no 21, Opinião Consultiva Request for an Advisory Opinion submitted by the Sub-Regional Fisheries Commission (SRFC) (Request for Advisory Opinion submitted to the Tribunal), o Tribunal Internacional do Direito do Mar (TIDM) reconheceu que a União Europeia pode ser responsabilizada (liability), na qualidade de organização internacional e parte da CNUDM, pela violação da legislação pesqueira de um Estado costeiro, ocasionada por navio arvorando pavilhão ou bandeira de um de seus Estados-membros, titular de uma licença de pesca emitida no âmbito de um acordo de acesso à pesca, a depender de o respectivo acordo conter disposições específicas relativas à responsabil', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q33 Item 4 (TPS 2022): Tendo em vista o estágio atual do direito internacional do mar na sociedade internacional, com o reconhecimento da atuação crescente de organizações e tribunais internacionais, respectivamente, na resolução de problemas globais e de controvérsias internacionais, julgue (C ou E) os itens a seguir. | No caso Chagos Marine Protected Area Arbitration (Mauritius v. United Kingdom), relativo ao estabelecimento de uma área marinha protegida pelo Reino Unido em torno do arquipélago de Chagos, tendo a Corte Permanente de Arbitragem servido apenas como registry, o Tribunal Arbitral, constituído em conformidade com o art. 287 e com o anexo VII da Convenção das Nações Unidas sobre o Direito do Mar CNUDM, concluiu que o Reino Unido tem a obrigação de pôr fim à administração do Arquipélago de Chagos o mais rapidamente possível e de que todos os Estados-membros devem cooperar com a Organização das Nações Unidas para completar a descolonização de Maurício. Área Livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q34 Item 1 (TPS 2022): Quanto às problemáticas da nacionalidade, de situação jurídica do estrangeiro e da apatridia, considerando o sistema jurídico brasileiro em sua completude, julgue (C ou E) os itens a seguir. | De acordo com o ordenamento jurídico brasileiro, será declarada a perda da nacionalidade do brasileiro que adquirir outra nacionalidade, salvo nos casos de reconhecimento de nacionalidade originária pela lei estrangeira ou de imposição de naturalização, pela norma estrangeira, ao brasileiro residente em estado estrangeiro, como condição para permanência em seu território ou para o exercício de direitos civis.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Economia', NULL, 'Q34 Item 2 (TPS 2022): Quanto às problemáticas da nacionalidade, de situação jurídica do estrangeiro e da apatridia, considerando o sistema jurídico brasileiro em sua completude, julgue (C ou E) os itens a seguir. | Em harmonia com o novo marco normativo das migrações no Brasil, inaugurado pela Lei de Migração, o visto temporário para acolhida humanitária poderá ser concedido ao apátrida ou ao nacional de qualquer país em situação de grave ou iminente instabilidade institucional, de conflito armado, de calamidade de grande proporção, de desastre ambiental ou de grave violação de direitos humanos ou de direito internacional humanitário, ou em outras hipóteses, na forma de regulamento.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
